<?php
declare(strict_types=1);
/** Millennium Probe engine. Uses the local oscillator PHP functions; no same-domain HTTP calls. */
if (!defined('MTZ_PROBE_TTL')) define('MTZ_PROBE_TTL', 12345);
if (!defined('MTZ_PROBE_LOG_FILE')) define('MTZ_PROBE_LOG_FILE', __DIR__ . '/millennium-probe.log');
require_once dirname(__DIR__) . '/palmier/oscillator/palmier-oscillator.php';
if (!function_exists('mtz_probe_phase_bounds')) { function mtz_probe_phase_bounds(int $year): array { return [[gmmktime(0,0,0,1,10,$year),gmmktime(23,59,59,3,15,$year)],[gmmktime(0,0,0,3,16,$year),gmmktime(23,59,59,5,25,$year)],[gmmktime(0,0,0,5,26,$year),gmmktime(23,59,59,8,5,$year)],[gmmktime(0,0,0,8,15,$year),gmmktime(23,59,59,10,15,$year)],[gmmktime(0,0,0,10,16,$year),gmmktime(23,59,59,12,20,$year)]]; } }
if (!function_exists('mtz_probe_phase_labels')) { function mtz_probe_phase_labels(): array { return ['Jan 10 – Mar 15','Mar 16 – May 25','May 26 – Aug 5','Aug 15 – Oct 15','Oct 16 – Dec 20']; } }
if (!function_exists('mtz_probe_find_phase')) { function mtz_probe_find_phase(int $now): array { $year=(int)gmdate('Y',$now);$bounds=mtz_probe_phase_bounds($year);foreach($bounds as $i=>$b){if($now >= $b[0] && $now <= $b[1])return [$i,$b[0],$b[1],$year];}if($now<$bounds[0][0]){$p=mtz_probe_phase_bounds($year-1);return [4,$p[4][0],$p[4][1],$year-1];} $n=mtz_probe_phase_bounds($year+1);return [0,$n[0][0],$n[0][1],$year+1]; } }
if (!function_exists('mtz_probe_amplitude')) { function mtz_probe_amplitude(float $osc): float { return 74144.0*(1.0+$osc); } }
if (!function_exists('mtz_probe_value')) { function mtz_probe_value(int $t,int $start,int $end,float $osc): float { $a=mtz_probe_amplitude($osc);$span=max(1,$end-$start+1);$u=($t-$start)/$span;if($u<0.25)return $a*sin(($u/0.25)*(M_PI/2));if($u<0.5)return $a*cos((($u-0.25)/0.25)*(M_PI/2));if($u<0.75)return -$a*sin((($u-0.5)/0.25)*(M_PI/2));return -$a*cos((($u-0.75)/0.25)*(M_PI/2)); } }
if (!function_exists('mtz_probe_read_last')) { function mtz_probe_read_last(): ?array { if(!is_file(MTZ_PROBE_LOG_FILE))return null;$lines=@file(MTZ_PROBE_LOG_FILE,FILE_IGNORE_NEW_LINES|FILE_SKIP_EMPTY_LINES);if(!$lines)return null;for($i=count($lines)-1;$i>=0;$i--){$v=json_decode($lines[$i],true);if(is_array($v)&&isset($v['timestamp'],$v['probe_iso']))return $v;}return null; } }
if (!function_exists('mtz_get_probe_result')) {
 function mtz_get_probe_result(bool $force=false): array { $now=time();$last=mtz_probe_read_last();if(!$force&&$last&&$now-(int)$last['timestamp']<MTZ_PROBE_TTL){$last['cache_age_seconds']=$now-(int)$last['timestamp'];$last['stale']=false;return $last;}$oscData=bzj_osc_get_data($force);$osc=(float)($oscData['oscillation_index']??0.0);[$idx,$start,$end,$phaseYear]=mtz_probe_find_phase($now);$value=mtz_probe_value($now,$start,$end,$osc);$payload=['status'=>'ok','timestamp'=>$now,'now_iso'=>gmdate('Y-m-d\TH:i:s\Z',$now),'phase_index'=>$idx+1,'phase_label'=>mtz_probe_phase_labels()[$idx],'phase_year'=>$phaseYear,'phase_start_iso'=>gmdate('Y-m-d\TH:i:s\Z',$start),'phase_end_iso'=>gmdate('Y-m-d\TH:i:s\Z',$end),'oscillation_index'=>$osc,'oscillation'=>$oscData['oscillation']??0,'amplitude_days'=>mtz_probe_amplitude($osc),'probe_value_days'=>$value,'probe_iso'=>gmdate('Y-m-d\TH:i:s\Z',$now+(int)round($value*86400)),'cache_age_seconds'=>0,'stale'=>false];$dir=dirname(MTZ_PROBE_LOG_FILE);if(!is_dir($dir))@mkdir($dir,0775,true);@file_put_contents(MTZ_PROBE_LOG_FILE,json_encode($payload,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE).PHP_EOL,FILE_APPEND|LOCK_EX);return $payload; }
}
if (isset($_SERVER['SCRIPT_FILENAME']) && realpath((string)$_SERVER['SCRIPT_FILENAME']) === __FILE__) { $p=mtz_get_probe_result(isset($_GET['force']));if(($_GET['probe']??'')==='now'||($_GET['format']??'')==='json'){header('Content-Type: application/json; charset=UTF-8');echo json_encode($p,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES);exit;}?><!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Millennium Probe</title><style>body{font:16px Arial;background:#101827;color:#fff;padding:24px}dt{font-weight:bold;margin-top:10px}dd{margin:4px 0}</style><h1>Millennium Probe</h1><dl><?php foreach($p as $k=>$v):?><dt><?=htmlspecialchars((string)$k,ENT_QUOTES,'UTF-8')?></dt><dd><?=htmlspecialchars(is_scalar($v)?(string)$v:json_encode($v),ENT_QUOTES,'UTF-8')?></dd><?php endforeach;?></dl><a href="?probe=now">JSON endpoint</a></html><?php }
